'use client';

import type React from 'react';
import FileTreeItem from './FileTreeItem';
import type { FileNode } from '@/types';
import { SidebarMenu } from '@/components/ui/sidebar';
import { ScrollArea } from '@/components/ui/scroll-area';
import SearchBar from './SearchBar'; // Импортируем компонент строки поиска
import { useState, useCallback, useRef } from 'react';
import dynamic from 'next/dynamic';

// Импорт pdfjs только на клиенте, чтобы избежать ReferenceError: DOMMatrix is not defined на сервере
const isClient = typeof window !== 'undefined';
let pdfjsLib: any = null;
if (isClient) {
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  pdfjsLib = require('pdfjs-dist/build/pdf');
  pdfjsLib.GlobalWorkerOptions.workerSrc =
    '//cdnjs.cloudflare.com/ajax/libs/pdf.js/' + pdfjsLib.version + '/pdf.worker.min.js';
}

interface FileTreeViewProps {
  nodes: FileNode[];
  onFileSelect: (file: FileNode) => void;
  selectedFileId?: string;
  searchTerm: string;
  expandedFolders: Set<string>;
  toggleFolder: (folderId: string) => void;
}

const FileTreeView: React.FC<FileTreeViewProps> = ({
  nodes,
  onFileSelect,
  selectedFileId,
  searchTerm,
  expandedFolders,
  toggleFolder,
}) => {
  const [searchResults, setSearchResults] = useState<{id: string, name: string, file: FileNode}[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [searchValue, setSearchValue] = useState('');
  const [showDropdown, setShowDropdown] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Рекурсивно получить все файлы (PDF) из дерева
  const getAllFiles = (nodes: FileNode[]): FileNode[] => {
    return nodes.flatMap(node =>
      node.type === 'file' ? [node] : (node.children ? getAllFiles(node.children) : [])
    );
  };

  // Извлечь текст из PDF-файла по URL
  const extractTextFromPdf = async (url: string): Promise<string> => {
    if (!isClient || !pdfjsLib) return '';
    try {
      const loadingTask = pdfjsLib.getDocument(url);
      const pdf = await loadingTask.promise;
      let text = '';
      for (let i = 1; i <= pdf.numPages; i++) {
        const page = await pdf.getPage(i);
        const content = await page.getTextContent();
        text += content.items.map((item: any) => item.str).join(' ') + ' ';
      }
      return text;
    } catch (e) {
      return '';
    }
  };

  // Поиск по содержимому PDF
  const handleTextSearch = useCallback(async (term: string) => {
    setSearchValue(term);
    if (!term.trim()) {
      setSearchResults([]);
      setShowDropdown(false);
      return;
    }
    setIsSearching(true);
    setShowDropdown(true);
    const files = getAllFiles(nodes).filter(f => f.path && f.path.endsWith('.pdf'));
    const lowerTerm = term.toLowerCase();
    const matches: {id: string, name: string, file: FileNode}[] = [];
    for (const file of files) {
      if (!file.path) continue;
      const text = await extractTextFromPdf(file.path);
      if (text.toLowerCase().includes(lowerTerm)) {
        matches.push({id: file.id, name: file.name, file});
      }
    }
    setSearchResults(matches);
    setIsSearching(false);
    setShowDropdown(true);
  }, [nodes]);

  // Обработчик выбора результата поиска
  const handleResultClick = (file: FileNode) => {
    setShowDropdown(false);
    setSearchResults([]);
    setSearchValue('');
    onFileSelect(file);
  };

  // Фильтрация: если есть результаты поиска по тексту, показываем только их
  const filterNodesBySearchResults = (nodesToFilter: FileNode[]): FileNode[] => {
    if (!searchResults.length) return nodesToFilter;
    function rFilter(array: FileNode[]): FileNode[] {
      return array.reduce<FileNode[]>((acc, node) => {
        if (node.type === 'file') {
          if (searchResults.includes(node.id)) acc.push(node);
        } else {
          const filteredChildren = node.children ? rFilter(node.children) : [];
          if (filteredChildren.length > 0) {
            acc.push({ ...node, children: filteredChildren });
          }
        }
        return acc;
      }, []);
    }
    return rFilter(nodesToFilter);
  };

  const displayedNodes = searchResults.length ? filterNodesBySearchResults(nodes) : nodes;

  return (
    <ScrollArea className="h-full flex-1">
      <SidebarMenu className="p-2" style={{position: 'relative'}}>
        {/* Новая строка поиска */}
        <SearchBar
          placeholder="Пошук по тексту PDF..."
          onSearch={handleTextSearch}
        />
        {isSearching && <div style={{padding: 8, color: '#888'}}>Пошук у PDF...</div>}
        {showDropdown && searchResults.length > 0 && (
          <div ref={dropdownRef} style={{
            position: 'absolute',
            top: 48,
            left: 0,
            right: 0,
            background: '#fff',
            border: '1px solid #ccc',
            borderRadius: 4,
            zIndex: 1000,
            maxHeight: 250,
            overflowY: 'auto',
            boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
          }}>
            {searchResults.map(result => (
              <div
                key={result.id}
                style={{ padding: 8, cursor: 'pointer', borderBottom: '1px solid #eee' }}
                onClick={() => handleResultClick(result.file)}
              >
                {result.name}
              </div>
            ))}
          </div>
        )}
        {displayedNodes.map((node) => (
          <FileTreeItem
            key={node.id}
            node={node}
            onFileSelect={onFileSelect}
            selectedFileId={selectedFileId}
            searchTerm={searchTerm}
            expandedFolders={expandedFolders}
            toggleFolder={toggleFolder}
            level={0}
          />
        ))}
      </SidebarMenu>
    </ScrollArea>
  );
};

export default FileTreeView;

// В компоненте поиска и обработчике handleTextSearch реализовать поиск по содержимому PDF-файлов, а не по их названиям/пути.
// Для этого потребуется использовать библиотеку для чтения PDF (например, pdfjs-dist) и реализовать функцию, которая будет открывать PDF, извлекать текст и искать совпадения.
